import net.runelite.client.util.QuantityFormatter;

final class EmptyDropLootSourceBox extends JPanel
{
	private static final int ITEMS_PER_ROW = 5;
	private static final BufferedImage EMPTY_DROP_IMAGE = buildEmptyDropIcon(26);
	private static final Color DEFAULT_DROP_RATE_COLOR = new Color(170, 200, 255);
	private static final Color COMMON_DROP_RATE_COLOR = new Color(80, 210, 100);
	private static final Color RARE_DROP_RATE_COLOR = new Color(225, 80, 80);
	private static final int RARITY_MIN_SAMPLE = 25;

	private final ItemManager itemManager;
	private final TrackerSnapshot.SourceSnapshot source;
	private final boolean useHighAlchemyValue;
	private final Consumer<String> onResetSource;

	EmptyDropLootSourceBox(
		ItemManager itemManager,
		TrackerSnapshot.SourceSnapshot source,
		boolean useHighAlchemyValue,
		Consumer<String> onResetSource)
	{
		this.itemManager = itemManager;
		this.source = source;
		this.useHighAlchemyValue = useHighAlchemyValue;
		this.onResetSource = onResetSource;

		setLayout(new BorderLayout(0, 1));
		setBorder(new EmptyBorder(5, 0, 0, 0));
		setOpaque(false);

		add(buildTitleRow(), BorderLayout.NORTH);
		add(buildItemsGrid(), BorderLayout.CENTER);
		setComponentPopupMenu(buildPopupMenu());
	}

	private JPanel buildTitleRow()
	{
		JPanel titleRow = new JPanel();
		titleRow.setLayout(new BoxLayout(titleRow, BoxLayout.X_AXIS));
		titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR.darker());
		titleRow.setBorder(new EmptyBorder(7, 7, 7, 7));

		JLabel sourceLabel = new JLabel(source.getName() + " x " + source.getKills());
		sourceLabel.setFont(FontManager.getRunescapeSmallFont());
		sourceLabel.setForeground(Color.WHITE);
		sourceLabel.setMinimumSize(new Dimension(1, sourceLabel.getPreferredSize().height));
		titleRow.add(sourceLabel);
		titleRow.add(Box.createHorizontalGlue());

		long value = source.getTotalValue();
		JLabel valueLabel = new JLabel(QuantityFormatter.quantityToStackSize(value) + " gp");
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		valueLabel.setToolTipText((useHighAlchemyValue ? "HA: " : "GE: ") + QuantityFormatter.formatNumber(value) + " gp");
		titleRow.add(valueLabel);

		return titleRow;
	}

	private JPanel buildItemsGrid()
	{
		List<TrackerSnapshot.ItemSnapshot> sortedItems = new ArrayList<>(source.getItems());
		sortedItems.sort(Comparator.comparingLong(this::priceOf).reversed());

		final int emptyDrops = source.getEmptyDrops();
		final int totalSlots = sortedItems.size() + (emptyDrops > 0 ? 1 : 0);
		final int rows = Math.max(1, (totalSlots + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW);
		final int totalGridSlots = rows * ITEMS_PER_ROW;

		JPanel grid = new JPanel(new GridLayout(rows, ITEMS_PER_ROW, 1, 1));
		grid.setOpaque(false);

		for (int slot = 0; slot < totalGridSlots; slot++)
		{
			JPanel slotPanel = new JPanel(new BorderLayout());
			slotPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			slotPanel.setBorder(new EmptyBorder(2, 2, 2, 2));

			if (slot < sortedItems.size())
			{
				TrackerSnapshot.ItemSnapshot item = sortedItems.get(slot);
				addItemSlot(slotPanel, item);
			}
			else if (slot == sortedItems.size() && emptyDrops > 0)
			{
				addEmptyDropSlot(slotPanel, emptyDrops);
			}

			grid.add(slotPanel);
		}

		return grid;
	}

	private void addItemSlot(JPanel slotPanel, TrackerSnapshot.ItemSnapshot item)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);

		JLabel quantityLabel = new JLabel(QuantityFormatter.quantityToStackSize(item.getQuantity()));
		quantityLabel.setFont(FontManager.getRunescapeSmallFont());
		quantityLabel.setForeground(new Color(255, 232, 80));
		header.add(quantityLabel, BorderLayout.WEST);

		slotPanel.add(header, BorderLayout.NORTH);

		JLabel iconLabel = new JLabel();
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		iconLabel.setVerticalAlignment(SwingConstants.CENTER);
		iconLabel.setToolTipText(buildItemToolTip(item));

		AsyncBufferedImage image = itemManager.getImage(item.getItemId());
		image.addTo(iconLabel);
		slotPanel.add(iconLabel, BorderLayout.CENTER);

		JLabel dropRateLabel = new JLabel(formatDropRate(item.getDropRate()), SwingConstants.CENTER);
		dropRateLabel.setFont(FontManager.getRunescapeSmallFont());
		dropRateLabel.setForeground(dropRateTextColor(item.getDropRate(), item.getAggregateKills()));
		slotPanel.add(dropRateLabel, BorderLayout.SOUTH);
	}

	private void addEmptyDropSlot(JPanel slotPanel, int emptyDrops)
	{
		double emptyDropRate = source.getAggregateKills() > 0
			? (double) emptyDrops / source.getAggregateKills()
			: 0D;

		JLabel quantityLabel = new JLabel("x" + QuantityFormatter.formatNumber(emptyDrops));
		quantityLabel.setFont(FontManager.getRunescapeSmallFont());
		quantityLabel.setForeground(Color.WHITE);
		slotPanel.add(quantityLabel, BorderLayout.NORTH);

		JLabel iconLabel = new JLabel(new ImageIcon(EMPTY_DROP_IMAGE));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		iconLabel.setVerticalAlignment(SwingConstants.CENTER);
		iconLabel.setToolTipText(
			"<html>No drop x " + QuantityFormatter.formatNumber(emptyDrops)
				+ "<br>Drop rate: " + formatDropRate(emptyDropRate)
				+ "</html>");
		slotPanel.add(iconLabel, BorderLayout.CENTER);

		JLabel dropRateLabel = new JLabel(formatDropRate(emptyDropRate), SwingConstants.CENTER);
		dropRateLabel.setFont(FontManager.getRunescapeSmallFont());
		dropRateLabel.setForeground(dropRateTextColor(emptyDropRate, source.getAggregateKills()));
		slotPanel.add(dropRateLabel, BorderLayout.SOUTH);
	}

	private String buildItemToolTip(TrackerSnapshot.ItemSnapshot item)
	{
		long shownQuantity = item.getQuantity();
		long aggregateQuantity = item.getAggregateQuantity();
		StringBuilder tooltip = new StringBuilder("<html>");
		tooltip.append(item.getName());
		tooltip.append("<br>Shown quantity: ").append(QuantityFormatter.formatNumber(shownQuantity));
		tooltip.append("<br>Total quantity: ").append(QuantityFormatter.formatNumber(aggregateQuantity));
		tooltip.append("<br>Times dropped: ").append(QuantityFormatter.formatNumber(item.getDropCount()));
		tooltip.append("<br>Drop rate: ").append(formatDropRate(item.getDropRate()));

		tooltip.append("</html>");
		return tooltip.toString();
	}

	private long priceOf(TrackerSnapshot.ItemSnapshot item)
	{
		return useHighAlchemyValue ? item.getTotalHaPrice() : item.getTotalGePrice();
	}

	private Color dropRateTextColor(double rate, int aggregateKills)
	{
		if (aggregateKills < RARITY_MIN_SAMPLE)
		{
			return DEFAULT_DROP_RATE_COLOR;
		}

		double clampedRate = Math.max(0D, Math.min(1D, rate));
		return interpolateColor(RARE_DROP_RATE_COLOR, COMMON_DROP_RATE_COLOR, clampedRate);
	}

	private static Color interpolateColor(Color lowerColor, Color upperColor, double t)
	{
		t = Math.max(0D, Math.min(1D, t));
		int red = (int) Math.round(lowerColor.getRed() + (upperColor.getRed() - lowerColor.getRed()) * t);
		int green = (int) Math.round(lowerColor.getGreen() + (upperColor.getGreen() - lowerColor.getGreen()) * t);
		int blue = (int) Math.round(lowerColor.getBlue() + (upperColor.getBlue() - lowerColor.getBlue()) * t);
		return new Color(red, green, blue);
	}

	private static String formatDropRate(double rate)
	{
		double percent = Math.max(0D, rate) * 100D;
		if (percent >= 99.95D)
		{
			return "100%";
		}
		return String.format(Locale.US, "%.2f%%", percent);
	}

	private static BufferedImage buildEmptyDropIcon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(220, 50, 50));
		graphics.setStroke(new BasicStroke(3.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.drawOval(3, 3, size - 6, size - 6);
		graphics.drawLine(6, size - 6, size - 6, 6);
		graphics.dispose();
		return image;
	}

	private JPopupMenu buildPopupMenu()
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem resetEnemy = new JMenuItem("Reset " + source.getName());
		resetEnemy.addActionListener(e ->
		{
			int selected = JOptionPane.showConfirmDialog(
				this,
				"Delete all tracked data for \"" + source.getName() + "\"?",
				"Confirm reset",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE);
			if (selected == JOptionPane.YES_OPTION)
			{
				onResetSource.accept(source.getName());
			}
		});
		menu.add(resetEnemy);
		return menu;
	}
}

package com.loottracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("emptydroploottracker")
public interface EmptyDropLootTrackerConfig extends Config
{
	@ConfigItem(
		keyName = "useHighAlchemyValue",
		name = "Use High Alch Value",
		description = "Calculate values using high alchemy prices instead of Grand Exchange prices"
	)
	default boolean useHighAlchemyValue()
	{
		return false;
	}

	@Range(min = 2, max = 40)
	@ConfigItem(
		keyName = "killCreditTimeoutTicks",
		name = "Kill Credit Timeout",
		description = "How many game ticks a kill stays credited after your last damage hitsplat"
	)
	default int killCreditTimeoutTicks()
	{
		return 20;
	}

	@Range(min = 3, max = 20)
	@ConfigItem(
		keyName = "emptyDropDelayTicks",
		name = "Empty Drop Delay",
		description = "How many game ticks to wait after an NPC death before counting it as an empty drop"
	)
	default int emptyDropDelayTicks()
	{
		return 8;
	}
}

package com.loottracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
