import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

final class EmptyDropLootTrackerPanel extends PluginPanel
{
	private final ItemManager itemManager;
	private final EmptyDropLootTrackerPlugin plugin;
	private final JLabel totalKillsLabel = new JLabel();
	private final JLabel totalValueLabel = new JLabel();
	private final JPanel contentPanel = new ViewportWidthPanel();
	private final JLabel emptyLabel = new JLabel("No tracked kills yet.");
	private final JButton viewToggleButton = new JButton();
	private boolean perKillView;
	private TrackerSnapshot lastSnapshot = TrackerSnapshot.EMPTY;
	private boolean lastUseHighAlchemyValue;

	EmptyDropLootTrackerPanel(ItemManager itemManager, EmptyDropLootTrackerPlugin plugin)
	{
		this.itemManager = itemManager;
		this.plugin = plugin;

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(6, 6, 6, 6));

		add(buildSummaryPanel(), BorderLayout.NORTH);
		add(buildScrollPanel(), BorderLayout.CENTER);

		render(TrackerSnapshot.EMPTY, false);
	}

	void render(TrackerSnapshot snapshot, boolean useHighAlchemyValue)
	{
		lastSnapshot = snapshot;
		lastUseHighAlchemyValue = useHighAlchemyValue;

		totalKillsLabel.setText("Total count: " + QuantityFormatter.formatNumber(snapshot.getTotalKills()));
		String valuePrefix = useHighAlchemyValue ? "Total HA value: " : "Total value: ";
		totalValueLabel.setText(valuePrefix + QuantityFormatter.quantityToStackSize(snapshot.getTotalValue()) + " gp");
		totalValueLabel.setToolTipText(QuantityFormatter.formatNumber(snapshot.getTotalValue()) + " gp");

		contentPanel.removeAll();
		viewToggleButton.setText(perKillView ? "Per-kill view" : "Grouped view");

		var rows = perKillView ? snapshot.getKillEntries() : snapshot.getSources();
		if (rows.isEmpty())
		{
			contentPanel.add(emptyLabel);
		}
		else
		{
			for (TrackerSnapshot.SourceSnapshot source : rows)
			{
				contentPanel.add(new EmptyDropLootSourceBox(itemManager, source, useHighAlchemyValue, plugin::resetSourceData));
			}
		}

		contentPanel.revalidate();
		contentPanel.repaint();
	}

	void clear()
	{
		render(TrackerSnapshot.EMPTY, false);
	}

	private JPanel buildSummaryPanel()
	{
		JPanel summaryPanel = new JPanel();
		summaryPanel.setLayout(new BoxLayout(summaryPanel, BoxLayout.Y_AXIS));
		summaryPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summaryPanel.setBorder(new EmptyBorder(8, 8, 8, 8));

		totalKillsLabel.setForeground(Color.WHITE);
		totalKillsLabel.setFont(FontManager.getRunescapeSmallFont());

		totalValueLabel.setForeground(Color.WHITE);
		totalValueLabel.setFont(FontManager.getRunescapeSmallFont());

		JPanel controlsRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 4));
		controlsRow.setOpaque(false);
		viewToggleButton.setFocusable(false);
		viewToggleButton.setText("Grouped view");
		viewToggleButton.addActionListener(e ->
		{
			perKillView = !perKillView;
			render(lastSnapshot, lastUseHighAlchemyValue);
		});
		controlsRow.add(viewToggleButton);

		JButton resetAllButton = new JButton("Reset all data");
		resetAllButton.setFocusable(false);
		resetAllButton.addActionListener(e ->
		{
			int selected = JOptionPane.showConfirmDialog(
				this,
				"Delete all tracked loot and kill data?",
				"Confirm reset",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE);
			if (selected == JOptionPane.YES_OPTION)
			{
				plugin.resetAllData();
			}
		});
		controlsRow.add(resetAllButton);

		summaryPanel.add(totalKillsLabel);
		summaryPanel.add(totalValueLabel);
		summaryPanel.add(controlsRow);
		return summaryPanel;
	}

	private JScrollPane buildScrollPanel()
	{
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setBorder(new EmptyBorder(12, 0, 0, 0));
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());

		JScrollPane scrollPane = new JScrollPane(contentPanel);
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setBorder(null);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		return scrollPane;
	}

	private static final class ViewportWidthPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

