@PluginDescriptor(
	name = "Loot Tracker Empty Drops",
	description = "Tracks NPC kills and loot, including empty drops",
	tags = {"loot", "drops", "tracker", "kills"}
)
@Slf4j
public class EmptyDropLootTrackerPlugin extends Plugin
{
	private static final int PENDING_KILL_EXPIRE_TICKS = 40;
	private static final int DUPLICATE_LOOT_EXPIRE_TICKS = 2;
	private static final int MAX_KILL_ENTRIES = 1024;
	private static final String CONFIG_GROUP = "emptydroploottracker";
	private static final String STORED_STATE_KEY = "storedState";

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EmptyDropLootTrackerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	private EmptyDropLootTrackerPanel panel;
	private NavigationButton navigationButton;

	private final Map<String, SourceStats> sourceStats = new LinkedHashMap<>();
	private final Deque<KillRecord> killRecords = new LinkedList<>();
	private final Map<Integer, Integer> lastDamageTickByNpcIndex = new HashMap<>();
	private final Map<Integer, PendingKill> pendingKillsByNpcIndex = new HashMap<>();
	private final Map<LootFingerprint, RecentLootEvent> recentLootFingerprints = new HashMap<>();

	private long sequenceCounter;
	private int totalKills;

	@Override
	protected void startUp()
	{
		panel = new EmptyDropLootTrackerPanel(itemManager, this);
		navigationButton = NavigationButton.builder()
			.tooltip("Loot Tracker + Empty Drops")
			.priority(7)
			.icon(buildSidebarIcon(16))
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navigationButton);
		loadState();
		refreshPanel();
	}

	@Override
	protected void shutDown()
	{
		saveState();

		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}

		resetAll();

		if (panel != null)
		{
			panel.clear();
			panel = null;
		}
	}

	@Provides
	EmptyDropLootTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EmptyDropLootTrackerConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			clearTransientCombatState();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		int maxCreditAge = Math.max(2, config.killCreditTimeoutTicks());
		int emptyDropDelay = Math.max(2, config.emptyDropDelayTicks());

		lastDamageTickByNpcIndex.entrySet().removeIf(entry -> tick - entry.getValue() > maxCreditAge);
		pendingKillsByNpcIndex.entrySet().removeIf(entry ->
		{
			PendingKill pendingKill = entry.getValue();
			if (!pendingKill.counted && tick - pendingKill.deathTick >= emptyDropDelay)
			{
				commitEmptyKill(pendingKill.sourceName, pendingKill);
			}
			return tick - pendingKill.deathTick > PENDING_KILL_EXPIRE_TICKS;
		});
		recentLootFingerprints.entrySet().removeIf(entry -> tick - entry.getValue().tick > DUPLICATE_LOOT_EXPIRE_TICKS);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("emptydroploottracker".equals(event.getGroup()))
		{
			refreshPanel();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		if (hitsplat == null || !hitsplat.isMine() || hitsplat.getAmount() <= 0)
		{
			return;
		}

		NPC npc = (NPC) actor;
		int tick = client.getTickCount();
		lastDamageTickByNpcIndex.put(npc.getIndex(), tick);
		log.debug("Credited damage npcIndex={} npcId={} name={} combatLevel={} tick={} damage={}",
			npc.getIndex(), npc.getId(), cleanName(npc.getName()), npc.getCombatLevel(), tick, hitsplat.getAmount());
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) actor;
		String npcName = cleanName(npc.getName());
		if (npcName == null)
		{
			log.debug("Ignoring NPC death with empty name npcIndex={} npcId={}", npc.getIndex(), npc.getId());
			return;
		}

		Integer lastDamageTick = lastDamageTickByNpcIndex.get(npc.getIndex());
		if (!isLikelyOurKill(npc, lastDamageTick))
		{
			log.debug("Ignoring uncredited NPC death source={} npcIndex={} npcId={} combatLevel={} deathTick={} lastDamageTick={} timeout={}",
				npcName, npc.getIndex(), npc.getId(), npc.getCombatLevel(), client.getTickCount(), lastDamageTick,
				config.killCreditTimeoutTicks());
			return;
		}

		int tick = client.getTickCount();
		PendingKill existingPending = pendingKillsByNpcIndex.get(npc.getIndex());
		if (existingPending != null && existingPending.deathTick == tick)
		{
			return;
		}

		PendingKill pendingKill = new PendingKill(npcName, npc.getIndex(), npc.getId(), npc.getCombatLevel(), tick, lastDamageTick);
		pendingKillsByNpcIndex.put(npc.getIndex(), pendingKill);
		log.debug("Registered pending kill source={} npcIndex={} npcId={} combatLevel={} deathTick={} lastDamageTick={}",
			npcName, npc.getIndex(), npc.getId(), npc.getCombatLevel(), tick, lastDamageTick);
	}

