	private void recordLoot(String sourceName, Collection<ItemStack> itemStacks, Integer npcIndex, String eventType)
	{
		if (sourceName == null || itemStacks == null || itemStacks.isEmpty())
		{
			log.debug("Ignoring empty loot event type={} source={} npcIndex={} itemCount={}",
				eventType, sourceName, npcIndex, itemStacks == null ? 0 : itemStacks.size());
			return;
		}

		Map<Integer, Long> itemQuantities = canonicalizeItemStacks(itemStacks);
		if (itemQuantities.isEmpty())
		{
			log.debug("Ignoring loot event with no positive quantities type={} source={} npcIndex={}",
				eventType, sourceName, npcIndex);
			return;
		}

		LootFingerprint fingerprint = LootFingerprint.create(sourceName, itemQuantities);
		int tick = client.getTickCount();
		PendingKill matchedKill = matchPendingKill(sourceName, npcIndex);
		if (isDuplicateLoot(fingerprint, tick, npcIndex, matchedKill))
		{
			log.debug("Suppressing duplicate loot type={} source={} npcIndex={} tick={} pending={} items={}",
				eventType, sourceName, npcIndex, tick, describePendingKill(matchedKill), itemQuantities);
			return;
		}
		recentLootFingerprints.put(fingerprint, new RecentLootEvent(tick, npcIndex, matchedKill));

		SourceStats source = sourceStats.computeIfAbsent(sourceName, ignored -> new SourceStats(sourceName));
		Collection<Integer> sourceDropCountItemIds = null;

		if (matchedKill == null)
		{
			source.kills++;
			totalKills++;
			KillRecord killRecord = pushKillRecord(sourceName);
			mergeItems(killRecord.itemsById, itemQuantities, true);
			killRecord.emptyDrop = false;
			log.debug("Counted loot as standalone kill type={} source={} npcIndex={} tick={} items={}",
				eventType, sourceName, npcIndex, tick, itemQuantities);
		}
		else
		{
			if (!matchedKill.counted)
			{
				source.kills++;
				totalKills++;
				KillRecord killRecord = pushKillRecord(sourceName);
				mergeItems(killRecord.itemsById, itemQuantities, true);
				killRecord.emptyDrop = false;
				matchedKill.killRecord = killRecord;
				matchedKill.counted = true;
				matchedKill.emptyCommitted = false;
				log.debug("Confirmed pending kill with loot type={} source={} npcIndex={} tick={} pending={} items={}",
					eventType, sourceName, npcIndex, tick, describePendingKill(matchedKill), itemQuantities);
			}
			else if (matchedKill.emptyCommitted)
			{
				source.emptyDrops = Math.max(0, source.emptyDrops - 1);
				matchedKill.killRecord.emptyDrop = false;
				mergeItems(matchedKill.killRecord.itemsById, itemQuantities, true);
				matchedKill.emptyCommitted = false;
				log.debug("Converted empty kill to loot type={} source={} npcIndex={} tick={} pending={} items={}",
					eventType, sourceName, npcIndex, tick, describePendingKill(matchedKill), itemQuantities);
			}
			else
			{
				sourceDropCountItemIds = getNewItemIds(matchedKill.killRecord, itemQuantities);
				mergeItems(matchedKill.killRecord.itemsById, itemQuantities, sourceDropCountItemIds);
				log.debug("Merged additional loot into confirmed kill type={} source={} npcIndex={} tick={} pending={} items={}",
					eventType, sourceName, npcIndex, tick, describePendingKill(matchedKill), itemQuantities);
			}
			matchedKill.lootFingerprints.put(fingerprint, tick);
		}

		source.lastUpdatedSequence = ++sequenceCounter;
		mergeItems(source.itemsById, itemQuantities, sourceDropCountItemIds);
		saveState();
		refreshPanel();
	}

	private Map<Integer, Long> canonicalizeItemStacks(Collection<ItemStack> itemStacks)
	{
		Map<Integer, Long> itemQuantities = new LinkedHashMap<>();
		for (ItemStack stack : itemStacks)
		{
			int itemId = itemManager.canonicalize(stack.getId());
			long quantity = stack.getQuantity();
			if (quantity <= 0)
			{
				continue;
			}

			itemQuantities.merge(itemId, quantity, Long::sum);
		}
		return itemQuantities;
	}

	private void mergeItems(Map<Integer, ItemStats> itemsById, Map<Integer, Long> itemQuantities, boolean incrementDropCount)
	{
		mergeItems(itemsById, itemQuantities, incrementDropCount ? null : new ArrayList<>());
	}

	private void mergeItems(Map<Integer, ItemStats> itemsById, Map<Integer, Long> itemQuantities,
		Collection<Integer> dropCountItemIds)
	{
		for (Map.Entry<Integer, Long> entry : itemQuantities.entrySet())
		{
			int itemId = entry.getKey();
			long quantity = entry.getValue();
			if (quantity <= 0)
			{
				continue;
			}

			ItemStats stats = itemsById.get(itemId);
			if (stats == null)
			{
				ItemComposition itemComposition = itemManager.getItemComposition(itemId);
				String name = itemComposition.getName();
				int gePrice = itemManager.getItemPrice(itemId);
				int haPrice = itemComposition.getHaPrice();
				stats = new ItemStats(itemId, name, gePrice, haPrice);
				itemsById.put(itemId, stats);
			}

			stats.quantity += quantity;
			if (dropCountItemIds == null || dropCountItemIds.contains(itemId))
			{
				stats.dropCount++;
			}
		}
	}

	private static List<Integer> getNewItemIds(KillRecord killRecord, Map<Integer, Long> itemQuantities)
	{
		List<Integer> itemIds = new ArrayList<>();
		for (Integer itemId : itemQuantities.keySet())
		{
			if (!killRecord.itemsById.containsKey(itemId))
			{
				itemIds.add(itemId);
			}
		}
		return itemIds;
	}

	private PendingKill matchPendingKill(String sourceName, Integer npcIndex)
	{
		int tick = client.getTickCount();
		PendingKill byIndex = npcIndex == null ? null : pendingKillsByNpcIndex.get(npcIndex);
		if (byIndex != null && byIndex.sourceName.equals(sourceName) && isMatchableByIndex(byIndex, tick))
		{
			return byIndex;
		}

		PendingKill bestCandidate = null;
		for (PendingKill candidate : pendingKillsByNpcIndex.values())
		{
			if (candidate.counted || !candidate.sourceName.equals(sourceName))
			{
				continue;
			}

			if (bestCandidate == null || candidate.deathTick > bestCandidate.deathTick)
			{
				bestCandidate = candidate;
			}
		}

		return bestCandidate;
	}

	private static boolean isMatchableByIndex(PendingKill pendingKill, int tick)
	{
		if (!pendingKill.counted || pendingKill.emptyCommitted)
		{
			return true;
		}

		return tick - pendingKill.deathTick <= DUPLICATE_LOOT_EXPIRE_TICKS;
	}

	private boolean isDuplicateLoot(LootFingerprint fingerprint, int tick, Integer npcIndex, PendingKill matchedKill)
	{
		if (matchedKill != null && matchedKill.lootFingerprints.containsKey(fingerprint))
		{
			return true;
		}

		RecentLootEvent recent = recentLootFingerprints.get(fingerprint);
		if (recent == null || tick != recent.tick)
		{
			return false;
		}

		if (matchedKill != null || recent.pendingKill != null)
		{
			if (matchedKill == null && npcIndex == null)
			{
				return true;
			}

			return matchedKill == recent.pendingKill;
		}

		return npcIndex == null || recent.npcIndex == null || npcIndex.equals(recent.npcIndex);
	}

	private boolean isLikelyOurKill(NPC npc, Integer lastDamageTick)
	{
		if (lastDamageTick == null)
		{
			return false;
		}

		int age = client.getTickCount() - lastDamageTick;
		return age >= 0 && age <= config.killCreditTimeoutTicks();
	}

	private TrackerSnapshot buildSnapshot()
	{
		List<TrackerSnapshot.SourceSnapshot> sourceSnapshots = new ArrayList<>(sourceStats.size());
		List<TrackerSnapshot.SourceSnapshot> killEntrySnapshots = new ArrayList<>(killRecords.size());
		long totalValue = 0L;

		List<SourceStats> sortedSources = new ArrayList<>(sourceStats.values());
		sortedSources.sort(Comparator.comparingLong(stats -> -stats.lastUpdatedSequence));

		for (SourceStats source : sortedSources)
		{
			long sourceValue = 0L;
			List<TrackerSnapshot.ItemSnapshot> itemSnapshots = new ArrayList<>(source.itemsById.size());
			for (ItemStats item : source.itemsById.values())
			{
				long itemValue = config.useHighAlchemyValue()
					? (long) item.haPrice * item.quantity
					: (long) item.gePrice * item.quantity;
				sourceValue += itemValue;

				itemSnapshots.add(new TrackerSnapshot.ItemSnapshot(
					item.itemId,
					item.name,
					item.quantity,
					item.quantity,
					item.dropCount,
					source.kills,
					item.gePrice,
					item.haPrice));
			}

			totalValue += sourceValue;
			sourceSnapshots.add(new TrackerSnapshot.SourceSnapshot(
				source.name,
				source.kills,
				source.kills,
				source.emptyDrops,
				sourceValue,
				itemSnapshots
			));
		}

		for (KillRecord killRecord : killRecords)
		{
			long killValue = 0L;
			List<TrackerSnapshot.ItemSnapshot> itemSnapshots = new ArrayList<>(killRecord.itemsById.size());
			SourceStats aggregateSource = sourceStats.get(killRecord.sourceName);
			int aggregateKills = aggregateSource == null ? 0 : aggregateSource.kills;
			for (ItemStats item : killRecord.itemsById.values())
			{
				long itemValue = config.useHighAlchemyValue()
					? (long) item.haPrice * item.quantity
					: (long) item.gePrice * item.quantity;
				killValue += itemValue;

				long aggregateQuantity = item.quantity;
				long dropCount = item.dropCount;
				if (aggregateSource != null)
				{
					ItemStats aggregateItem = aggregateSource.itemsById.get(item.itemId);
					if (aggregateItem != null)
					{
						aggregateQuantity = aggregateItem.quantity;
						dropCount = aggregateItem.dropCount;
					}
				}

				itemSnapshots.add(new TrackerSnapshot.ItemSnapshot(
					item.itemId,
					item.name,
					item.quantity,
					aggregateQuantity,
					dropCount,
					aggregateKills,
					item.gePrice,
					item.haPrice));
			}

			killEntrySnapshots.add(new TrackerSnapshot.SourceSnapshot(
				killRecord.sourceName,
				1,
				aggregateKills,
				killRecord.emptyDrop ? 1 : 0,
				killValue,
				itemSnapshots
			));
		}

		return new TrackerSnapshot(totalKills, totalValue, sourceSnapshots, killEntrySnapshots);
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		TrackerSnapshot snapshot = buildSnapshot();
		SwingUtilities.invokeLater(() -> panel.render(snapshot, config.useHighAlchemyValue()));
	}

	private void resetAll()
	{
		sourceStats.clear();
		killRecords.clear();
		totalKills = 0;
		sequenceCounter = 0;
		clearTransientCombatState();
	}

	void resetAllData()
	{
		resetAll();
		saveState();
		refreshPanel();
	}

	void resetSourceData(String sourceName)
	{
		if (sourceName == null || sourceName.isEmpty())
		{
			return;
		}

		SourceStats removed = sourceStats.remove(sourceName);
		if (removed == null)
		{
			return;
		}

		totalKills = Math.max(0, totalKills - removed.kills);
		killRecords.removeIf(k -> sourceName.equals(k.sourceName));
		pendingKillsByNpcIndex.entrySet().removeIf(e -> sourceName.equals(e.getValue().sourceName));

		saveState();
		refreshPanel();
	}

	private void clearTransientCombatState()
	{
		lastDamageTickByNpcIndex.clear();
		pendingKillsByNpcIndex.clear();
		recentLootFingerprints.clear();
	}

	private void saveState()
	{
		StoredState state = new StoredState();
		state.totalKills = totalKills;
		state.sequenceCounter = sequenceCounter;

		for (SourceStats source : sourceStats.values())
		{
			StoredSource storedSource = new StoredSource();
			storedSource.name = source.name;
			storedSource.kills = source.kills;
			storedSource.emptyDrops = source.emptyDrops;
			storedSource.lastUpdatedSequence = source.lastUpdatedSequence;

			for (ItemStats item : source.itemsById.values())
			{
				storedSource.items.add(toStoredItem(item));
			}

			state.sources.add(storedSource);
		}

		for (KillRecord killRecord : killRecords)
		{
			StoredKillRecord storedKill = new StoredKillRecord();
			storedKill.sourceName = killRecord.sourceName;
			storedKill.emptyDrop = killRecord.emptyDrop;
			for (ItemStats item : killRecord.itemsById.values())
			{
				storedKill.items.add(toStoredItem(item));
			}
			state.killRecords.add(storedKill);
		}

		configManager.setConfiguration(CONFIG_GROUP, STORED_STATE_KEY, gson.toJson(state));
	}

	private void loadState()
	{
		String raw = configManager.getConfiguration(CONFIG_GROUP, STORED_STATE_KEY);
		if (raw == null || raw.isEmpty())
		{
			return;
		}

		try
		{
			StoredState storedState = gson.fromJson(raw, StoredState.class);
			if (storedState == null)
			{
				return;
			}

			sourceStats.clear();
			killRecords.clear();
			totalKills = Math.max(0, storedState.totalKills);
			sequenceCounter = Math.max(0L, storedState.sequenceCounter);

			for (StoredSource storedSource : storedState.sources)
			{
				if (storedSource == null || storedSource.name == null || storedSource.name.isEmpty())
				{
					continue;
				}

				SourceStats source = new SourceStats(storedSource.name);
				source.kills = Math.max(0, storedSource.kills);
				source.emptyDrops = Math.max(0, storedSource.emptyDrops);
				source.lastUpdatedSequence = storedSource.lastUpdatedSequence;

				for (StoredItem storedItem : storedSource.items)
				{
					ItemStats item = fromStoredItem(storedItem);
					if (item != null)
					{
						source.itemsById.put(item.itemId, item);
					}
				}

				sourceStats.put(source.name, source);
			}

			for (StoredKillRecord storedKill : storedState.killRecords)
			{
				if (storedKill == null || storedKill.sourceName == null || storedKill.sourceName.isEmpty())
				{
					continue;
				}

				KillRecord killRecord = new KillRecord(storedKill.sourceName);
				killRecord.emptyDrop = storedKill.emptyDrop;
				for (StoredItem storedItem : storedKill.items)
				{
					ItemStats item = fromStoredItem(storedItem);
					if (item != null)
					{
						killRecord.itemsById.put(item.itemId, item);
					}
				}
				killRecords.add(killRecord);
			}

			reconcileSourceDropCountsFromKillHistory();
		}
		catch (JsonSyntaxException ex)
		{
			configManager.unsetConfiguration(CONFIG_GROUP, STORED_STATE_KEY);
		}
	}

	private void reconcileSourceDropCountsFromKillHistory()
	{
		Map<String, Map<Integer, Long>> historyCountsBySource = new HashMap<>();
		for (KillRecord killRecord : killRecords)
		{
			Map<Integer, Long> historyCountsByItem =
				historyCountsBySource.computeIfAbsent(killRecord.sourceName, ignored -> new HashMap<>());

			for (Integer itemId : killRecord.itemsById.keySet())
			{
				historyCountsByItem.merge(itemId, 1L, Long::sum);
			}
		}

		for (SourceStats source : sourceStats.values())
		{
			Map<Integer, Long> historyCountsByItem = historyCountsBySource.get(source.name);

			for (ItemStats item : source.itemsById.values())
			{
				long storedCount = Math.max(0L, item.dropCount);
				long historyCount = historyCountsByItem == null
					? 0L
					: historyCountsByItem.getOrDefault(item.itemId, 0L);

				// History is capped to MAX_KILL_ENTRIES, so keep whichever count is higher.
				long resolvedCount = historyCount > 0 ? Math.max(storedCount, historyCount) : storedCount;
				if (item.quantity > 0 && resolvedCount <= 0)
				{
					resolvedCount = 1;
				}
				if (item.dropCount != resolvedCount)
				{
					item.dropCount = resolvedCount;
				}
			}
		}
	}

	private static StoredItem toStoredItem(ItemStats item)
	{
		StoredItem stored = new StoredItem();
		stored.itemId = item.itemId;
		stored.name = item.name;
		stored.gePrice = item.gePrice;
		stored.haPrice = item.haPrice;
		stored.quantity = item.quantity;
		stored.dropCount = item.dropCount;
		return stored;
	}

	private static ItemStats fromStoredItem(StoredItem stored)
	{
		if (stored == null || stored.itemId <= 0 || stored.name == null)
		{
			return null;
		}

		ItemStats item = new ItemStats(
			stored.itemId,
			stored.name,
			Math.max(0, stored.gePrice),
			Math.max(0, stored.haPrice));
		item.quantity = Math.max(0L, stored.quantity);
		item.dropCount = Math.max(0L, stored.dropCount);
		if (item.quantity > 0 && item.dropCount == 0)
		{
			item.dropCount = 1;
		}
		return item.quantity > 0 ? item : null;
	}

	private static String cleanName(String rawName)
	{
		if (rawName == null)
		{
			return null;
		}

		String cleaned = Text.removeTags(rawName).trim();
		if (cleaned.isEmpty() || "null".equalsIgnoreCase(cleaned))
		{
			return null;
		}

		return cleaned;
	}

