		private final int npcIndex;
		private final int npcId;
		private final int combatLevel;
		private final int deathTick;
		private final int lastDamageTick;
		private final Map<LootFingerprint, Integer> lootFingerprints = new HashMap<>();
		private boolean counted;
		private boolean emptyCommitted;
		private KillRecord killRecord;

		private PendingKill(String sourceName, int npcIndex, int npcId, int combatLevel, int deathTick, int lastDamageTick)
		{
			this.sourceName = sourceName;
			this.npcIndex = npcIndex;
			this.npcId = npcId;
