	private KillRecord pushKillRecord(String sourceName)
	{
		KillRecord record = new KillRecord(sourceName);
		killRecords.addFirst(record);
		while (killRecords.size() > MAX_KILL_ENTRIES)
		{
			killRecords.removeLast();
		}
		return record;
	}

	private void commitEmptyKill(String sourceName, PendingKill pendingKill)
	{
		if (pendingKill.counted)
		{
			return;
		}

		SourceStats source = sourceStats.computeIfAbsent(sourceName, ignored -> new SourceStats(sourceName));
		source.kills++;
		source.emptyDrops++;
		source.lastUpdatedSequence = ++sequenceCounter;
		totalKills++;

		KillRecord killRecord = pushKillRecord(sourceName);
		pendingKill.killRecord = killRecord;
		pendingKill.counted = true;
		pendingKill.emptyCommitted = true;
		log.debug("Committed empty kill source={} npcIndex={} npcId={} combatLevel={} deathTick={} lastDamageTick={} emptyDelay={}",
			sourceName, pendingKill.npcIndex, pendingKill.npcId, pendingKill.combatLevel, pendingKill.deathTick,
			pendingKill.lastDamageTick, config.emptyDropDelayTicks());
		saveState();
		refreshPanel();
	}

	private static String describePendingKill(PendingKill pendingKill)
	{
		if (pendingKill == null)
		{
			return "none";
		}

		return "source=" + pendingKill.sourceName
			+ ",npcIndex=" + pendingKill.npcIndex
			+ ",npcId=" + pendingKill.npcId
			+ ",combatLevel=" + pendingKill.combatLevel
			+ ",deathTick=" + pendingKill.deathTick
			+ ",counted=" + pendingKill.counted
			+ ",emptyCommitted=" + pendingKill.emptyCommitted;
	}

