	private static final class LootFingerprint
	{
		private final String source;
		private final int size;
		private final long hash;

		private LootFingerprint(String source, int size, long hash)
		{
			this.source = source;
			this.size = size;
			this.hash = hash;
		}

		private static LootFingerprint create(String source, Map<Integer, Long> items)
		{
			long hash = 1L;
			for (Map.Entry<Integer, Long> item : items.entrySet())
			{
				hash = (hash * 31L) + item.getKey();
				hash = (hash * 31L) + item.getValue();
			}
			return new LootFingerprint(source, items.size(), hash);
		}

		@Override
		public int hashCode()
		{
			int result = source.hashCode();
			result = 31 * result + size;
			result = 31 * result + Long.hashCode(hash);
			return result;
		}

		@Override
		public boolean equals(Object obj)
		{
			if (this == obj)
			{
				return true;
			}
			if (!(obj instanceof LootFingerprint))
			{
				return false;
			}
			LootFingerprint other = (LootFingerprint) obj;
			return size == other.size && hash == other.hash && source.equals(other.source);
		}
	}

