package com.loottracker;

import java.util.Collections;
import java.util.List;

final class TrackerSnapshot
{
	static final TrackerSnapshot EMPTY = new TrackerSnapshot(0, 0L, Collections.emptyList(), Collections.emptyList());

	private final int totalKills;
	private final long totalValue;
	private final List<SourceSnapshot> sources;
	private final List<SourceSnapshot> killEntries;

	TrackerSnapshot(int totalKills, long totalValue, List<SourceSnapshot> sources, List<SourceSnapshot> killEntries)
	{
		this.totalKills = totalKills;
		this.totalValue = totalValue;
		this.sources = sources;
		this.killEntries = killEntries;
	}

	int getTotalKills()
	{
		return totalKills;
	}

	long getTotalValue()
	{
		return totalValue;
	}

	List<SourceSnapshot> getSources()
	{
		return sources;
	}

	List<SourceSnapshot> getKillEntries()
	{
		return killEntries;
	}

	static final class SourceSnapshot
	{
		private final String name;
		private final int kills;
		private final int aggregateKills;
		private final int emptyDrops;
		private final long totalValue;
		private final List<ItemSnapshot> items;

		SourceSnapshot(String name, int kills, int aggregateKills, int emptyDrops, long totalValue, List<ItemSnapshot> items)
		{
			this.name = name;
			this.kills = kills;
			this.aggregateKills = aggregateKills;
			this.emptyDrops = emptyDrops;
			this.totalValue = totalValue;
			this.items = items;
		}

		String getName()
		{
			return name;
		}

		int getKills()
		{
			return kills;
		}

		int getAggregateKills()
		{
			return aggregateKills;
		}

		int getEmptyDrops()
		{
			return emptyDrops;
		}

		long getTotalValue()
		{
			return totalValue;
		}

		List<ItemSnapshot> getItems()
		{
			return items;
		}
	}

	static final class ItemSnapshot
	{
		private final int itemId;
		private final String name;
		private final long quantity;
		private final long aggregateQuantity;
		private final long dropCount;
		private final int aggregateKills;
		private final int gePrice;
		private final int haPrice;

		ItemSnapshot(int itemId, String name, long quantity, long aggregateQuantity, long dropCount, int aggregateKills, int gePrice, int haPrice)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.aggregateQuantity = aggregateQuantity;
			this.dropCount = dropCount;
			this.aggregateKills = aggregateKills;
			this.gePrice = gePrice;
			this.haPrice = haPrice;
		}

		int getItemId()
		{
			return itemId;
		}

		String getName()
		{
			return name;
		}

		long getQuantity()
		{
			return quantity;
		}

		long getAggregateQuantity()
		{
			return aggregateQuantity;
		}

		long getDropCount()
		{
			return dropCount;
		}

		int getAggregateKills()
		{
			return aggregateKills;
		}

		int getGePrice()
		{
			return gePrice;
		}

		int getHaPrice()
		{
			return haPrice;
		}

		long getTotalGePrice()
		{
			return gePrice * quantity;
		}

		long getTotalHaPrice()
		{
			return haPrice * quantity;
		}

		double getDropRate()
		{
			if (aggregateKills <= 0)
			{
				return 0D;
			}
			return (double) dropCount / aggregateKills;
		}
	}
}

